import {surchargeBidLabel,surchargeBidHint} from './surcharge-display.js';
import {withBidLines,bidFixedCharges} from './bid-core.js';
import {manualCalculation} from './calculation-modes.js';
import {amount,totals,bidPercent,synchronizeLinkedCosts} from './calc.js';
import {matchingRate} from './est-edit.js';
export function setupEstActions({getProject,getLibraries,getGroup,getSelected,commit,toast}){
 const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>Number(n).toLocaleString('ko-KR');
 $('bidRows').insertAdjacentHTML('beforebegin',`<details class="bid-options"><summary>낙찰 대상과 제경비 금액 유지</summary><label class="check"><input id="bidSeparate" type="checkbox">폐기물·수수료 별도 항목도 선택 대상에 포함</label><p class="hint">유지할 제경비를 선택하세요. 선택 항목은 낙찰 전 금액으로 고정하고, 전체를 100%로 복원하면 기존 요율로 돌아갑니다.</p><div id="bidFixedOptions">${Object.entries(bidFixedCharges).map(([key,label])=>`<label class="check"><input type="checkbox" data-bid-fixed="${key}" checked>${label}</label>`).join('')}</div></details>`);
 const fixedKeys=()=>[...$('bidFixedOptions').querySelectorAll('[data-bid-fixed]:checked')].map(el=>el.dataset.bidFixed);
 let draft=[],checks=new Set(),refresh=[],undo=null,undoAfter=null,bulkTouched=false,bulkInvalid=false;
 const backup=()=>{undo=structuredClone(getProject());$('undoEstAction').disabled=false;};
 $('undoEstAction').onclick=()=>{if(!undo)return;if(JSON.stringify(getProject())!==undoAfter){undo=null;$('undoEstAction').disabled=true;toast('이후 편집 내용이 있어 직전 적용 취소를 중단했습니다. 낙찰률 창에서 100%로 복원할 수 있습니다.');return;}const p=getProject();Object.keys(p).forEach(k=>delete p[k]);Object.assign(p,undo);undo=null;$('undoEstAction').disabled=true;commit();toast('직전 낙찰·단가 갱신을 되돌렸습니다.');};
 function eligible(l){return !l.level&&!l.generatedSupplyFee&&!l.surcharge&&!l.deduction&&!l.exclude&&!manualCalculation(l)&&!l.rate?.evidenceBid&&l.bucket!=='government'&&!l.rate?.government&&((l.bucket||'direct')==='direct'||$('bidSeparate').checked);}
 function selected(l){return eligible(l)&&($('bidScope').value==='all'||($('bidScope').value==='group'&&l.group===getGroup())||($('bidScope').value==='line'&&l.id===getSelected()));}
 function preview(){
  const p=getProject(),next=p.lines.map(l=>checks.has(l.id)?draft.find(d=>d.id===l.id)||l:l);
  const before=totals(p.lines,p.charges),afterProject=withBidLines(p,next,fixedKeys()),after=totals(next,afterProject.charges);
  $('bidSummary').textContent=`선택 ${checks.size}건 · 도급 산정액 ${money(before.contract)} → ${money(after.contract)}원 · 관급 ${money(after.government)}원${after.missing?` · 미확정 ${after.missing}건 제외`:''}`;
  $('bidApply').disabled=!checks.size||bulkInvalid;
 }
 function renderBid(){
  draft=synchronizeLinkedCosts({...getProject(),lines:draft}).lines;
  $('bidRows').innerHTML='<table><thead><tr><th>적용</th><th>공종</th><th>품명 · 규격</th><th>낙찰률 %</th><th>현재 금액</th><th>적용 금액</th></tr></thead><tbody>'+draft.filter(l=>!l.level&&!l.exclude).map(l=>`<tr><td class="cell-center"><input type="checkbox" data-bid-check="${l.id}" ${checks.has(l.id)?'checked':''} ${eligible(l)?'':'disabled'} aria-label="${esc(l.name)} 낙찰 선택"></td><td>${esc(l.group)}</td><td>${esc(l.name)} <small>${esc(l.spec)}</small>${l.surcharge?' · 기준 노무비 낙찰 연동':eligible(l)?'':l.rate?.evidenceBid?' · 근거 낙찰 '+l.rate.evidenceBid.percent+'% 적용':manualCalculation(l)?' · 직접 입력 금액 유지':l.bucket==='government'||l.rate?.government?' · 관급 제외':' · 별도 항목 제외'}</td><td>${l.surcharge?`<span title="${esc(surchargeBidHint(l))}">${esc(surchargeBidLabel(l))}</span>`:`<input type="number" min="0" max="100" step="any" class="charge-rate" data-bid-value="${l.id}" value="${bidPercent(l)}" ${eligible(l)?'':'disabled'} aria-label="${esc(l.name)} 낙찰률">`}</td><td class="number">${amount(getProject().lines.find(x=>x.id===l.id))?money(amount(getProject().lines.find(x=>x.id===l.id)).total):'미확정'}</td><td class="number" data-bid-result="${l.id}">${amount(l)?money(amount(l).total):'미확정'}</td></tr>`).join('')+'</tbody></table>';preview();
 }
 function batch(){const p=Number($('bidRate').value);bulkTouched=true;bulkInvalid=!Number.isFinite(p)||p<0||p>100||!$('bidRate').value.trim();if(bulkInvalid){$('bidApply').disabled=true;$('bidSummary').textContent='낙찰률은 0~100%로 입력하세요.';return;}for(const l of draft)if(checks.has(l.id)){l.bidPercent=p;l.bidMethod=$('bidMethod').value;}renderBid();}
 $('bidBtn').onclick=()=>{draft=structuredClone(getProject().lines);$('bidSeparate').checked=false;const existing=getProject().charges.filter(c=>c.bidOriginal);for(const el of $('bidFixedOptions').querySelectorAll('[data-bid-fixed]'))el.checked=existing.length?existing.some(c=>c.key===el.dataset.bidFixed):true;$('bidScope').value='all';checks=new Set(draft.filter(eligible).map(l=>l.id));bulkTouched=false;bulkInvalid=false;const rates=[...new Set(draft.filter(eligible).map(bidPercent))];$('bidRate').value=rates.length===1?rates[0]:'';$('bidRate').placeholder='혼합';renderBid();$('bidDialog').showModal();};
 $('bidScope').onchange=()=>{checks=new Set(draft.filter(selected).map(l=>l.id));if(bulkTouched)batch();else renderBid();};
 $('bidSeparate').onchange=()=>{checks=new Set(draft.filter(selected).map(l=>l.id));if(bulkTouched)batch();else renderBid();};$('bidFixedOptions').onchange=preview;
 $('bidBatch').onclick=batch;$('bidRate').oninput=batch;$('bidMethod').onchange=()=>{for(const l of draft)if(checks.has(l.id))l.bidMethod=$('bidMethod').value;renderBid();};
 $('bidRestore').onclick=()=>{$('bidRate').value='100';batch();};
 $('bidRows').onchange=e=>{const id=e.target.dataset.bidCheck;if(id){if(e.target.checked)checks.add(id);else checks.delete(id);preview();return;}const l=draft.find(l=>l.id===e.target.dataset.bidValue);if(!l)return;const v=e.target.valueAsNumber;if(!Number.isFinite(v)||v<0||v>100){e.target.value=bidPercent(l);toast('낙찰률은 0~100%로 입력하세요.');return;}l.bidPercent=v;l.bidMethod=$('bidMethod').value;checks.add(l.id);bulkInvalid=false;renderBid();};
 $('bidApply').onclick=()=>{if(bulkInvalid||!checks.size)return;backup();const p=getProject();for(const l of p.lines){const d=draft.find(d=>d.id===l.id);if(d&&checks.has(l.id)){l.bidPercent=d.bidPercent??100;l.bidMethod=d.bidMethod??'unit';}}p.charges=withBidLines(undo,p.lines,fixedKeys()).charges;p.ratesReviewed=false;commit();undoAfter=JSON.stringify(getProject());$('bidDialog').close();toast('낙찰률을 적용했습니다. 원단가는 보존되어 100%로 복원할 수 있습니다.');};
 $('refreshRatesBtn').onclick=()=>{const libs=getLibraries().filter(l=>!l.userLibrary);$('refreshLibrary').innerHTML=libs.map(l=>`<option value="${esc(l.id)}">${esc(l.name)}</option>`).join('');if(!libs.length){toast('갱신할 DB를 먼저 추가하세요.');return;}makeRefresh();$('refreshDialog').showModal();};
 function makeRefresh(){const library=getLibraries().find(l=>l.id===$('refreshLibrary').value);refresh=[];if(!library)return;for(const l of getProject().lines){if(l.level||l.surcharge||l.deduction||l.exclude||!l.rate||l.status!=='confirmed')continue;const rate=matchingRate(l.rate,library);refresh.push({id:l.id,name:l.name,before:l.rate,rate});}
  $('refreshRows').innerHTML='<table><thead><tr><th>적용</th><th>품명</th><th>현재 단가</th><th>새 단가</th><th>확인</th></tr></thead><tbody>'+refresh.map((r,i)=>`<tr><td class="cell-center"><input type="checkbox" data-refresh="${i}" ${r.rate?'checked':'disabled'} aria-label="${esc(r.name)} 단가 갱신"></td><td>${esc(r.name)}</td><td class="number">${money(r.before.total)}</td><td class="number">${r.rate?money(r.rate.total):'—'}</td><td>${r.rate?'코드·품명·규격·단위 일치':'일치 항목 없음 · 유지'}</td></tr>`).join('')+'</tbody></table>';$('refreshApply').disabled=!refresh.some(r=>r.rate);
 }
 $('refreshLibrary').onchange=makeRefresh;
 $('refreshApply').onclick=()=>{const chosen=[...$('refreshRows').querySelectorAll('[data-refresh]:checked')].map(e=>refresh[Number(e.dataset.refresh)]).filter(r=>r.rate);if(!chosen.length)return;backup();for(const r of chosen){const line=getProject().lines.find(l=>l.id===r.id);line.rate=structuredClone(r.rate);}getProject().ratesReviewed=false;commit();undoAfter=JSON.stringify(getProject());$('refreshDialog').close();toast(`${chosen.length}개 내역의 연결 단가를 갱신했습니다.`);};
 return {resetUndo(){undo=null;$('undoEstAction').disabled=true;}};
}
